import{R as e,e as o,f as n,U as a}from"./chunks/framework.ywem4qy5.js";const m=JSON.parse('{"title":"IFTTT","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/automations/ifttt.md","filePath":"integrations/automations/ifttt.md","lastUpdated":1775908585000}'),i={name:"integrations/automations/ifttt.md"};function r(s,t,l,h,g,c){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="ifttt" tabindex="-1">IFTTT <a class="header-anchor" href="#ifttt" aria-label="Permalink to &quot;IFTTT&quot;">​</a></h1><p>Follow the below steps to connect to the IFTTT API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Automations</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>IFTTT</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-ifttt-api" tabindex="-1">Step 2. Connect to the IFTTT API <a class="header-anchor" href="#step-2-connect-to-the-ifttt-api" aria-label="Permalink to &quot;Step 2. Connect to the IFTTT API&quot;">​</a></h3><ol><li>Go to the <a href="https://ifttt.com/create" target="_blank">IFTTT Create page</a>.</li><li>Click <strong>If This → Add</strong>, then search for and select <strong>Webhooks</strong>.</li><li>Choose <strong>Receive a web request</strong> and enter an <strong>Event Name</strong> (e.g. <code>form_submission</code>). Make a note of <strong>Event Name</strong> for later.</li><li>Click <strong>Then That → Add</strong>, and choose an action like sending an email, Slack message, Google Sheets, etc.</li><li>Complete the applet and click <strong>Finish</strong>.</li></ol><h3 id="step-3-get-your-webhook-key" tabindex="-1">Step 3. Get Your Webhook Key <a class="header-anchor" href="#step-3-get-your-webhook-key" aria-label="Permalink to &quot;Step 3. Get Your Webhook Key&quot;">​</a></h3><ol><li>Visit <a href="https://ifttt.com/maker_webhooks" target="_blank"><a href="https://ifttt.com/maker_webhooks" target="_blank" rel="noreferrer">https://ifttt.com/maker_webhooks</a></a>.</li><li>Click <strong>Documentation</strong>.</li><li>Copy your <strong>Webhook Key</strong> from the URL shown (<code>https://maker.ifttt.com/use/XXXXX</code>).</li><li>Paste it into the <strong>Webhook Key</strong> field in Formie.</li><li>Enter the same <strong>Event Name</strong> you used in IFTTT.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li><li>Click on the <strong>Send Test Payload</strong> button to send dummy content to the URL.</li></ol>',10)])])}const f=e(i,[["render",r]]);export{m as __pageData,f as default};
